#!/usr/bin/env node
/**
 * Generates the PawCue clicker sounds from scratch.
 *
 * Everything here is synthesised from noise and damped sine modes — there is no sampled source material, so the
 * output is original by construction and carries no licensing question. The generator is source-controlled and
 * deterministic (seeded PRNG), so the committed WAVs can be regenerated byte-for-byte:
 *
 *     pnpm --filter @pawcue/mobile run audio:generate
 *
 * ## What a physical box clicker actually sounds like
 *
 * A metal tongue is snapped through a bistable position and strikes the plastic housing. Acoustically that is:
 *
 *   1. a broadband snap with a near-instant rise and an extremely fast decay (~2ms),
 *   2. a handful of lightly damped body resonances in the 1–5kHz range that die within ~10ms,
 *   3. a quieter second transient a few milliseconds later, as the tongue settles against the housing.
 *
 * Point 3 is what separates a clicker from a snare hit or a UI blip, and it is why each candidate below renders a
 * secondary transient rather than a single envelope. The modal decays are all kept short on purpose: long,
 * high-frequency modes are exactly what makes a sound read as "metallic" or "digital", both of which are ruled out.
 */

import { writeFileSync, mkdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const SAMPLE_RATE = 48_000;

/**
 * 48kHz rather than 44.1kHz: it is the native rate of the Android audio path and of current iOS hardware, so the
 * OS mixer never has to resample. Resampling a 40ms transient is precisely where a crisp attack gets smeared.
 */

/** Peak ceiling, -1 dBFS. Leaves headroom so no downstream gain stage clips. */
const PEAK_CEILING = 10 ** (-1 / 20);

/** Every candidate ends with this fade so the file cannot end on a non-zero sample (which is itself a click). */
const RELEASE_FADE_MS = 3;

// ---------------------------------------------------------------------------------------------------------------
// Deterministic noise
// ---------------------------------------------------------------------------------------------------------------

/** mulberry32 — small, fast, and seeded, so regenerating produces identical files. */
function mulberry32(seed) {
  let a = seed >>> 0;
  return function next() {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// ---------------------------------------------------------------------------------------------------------------
// Filters
// ---------------------------------------------------------------------------------------------------------------

/**
 * Chamberlin state-variable filter, bandpass tap.
 *
 * Used to give the noise burst a centre of gravity. Raw white noise reads as a "tss" — hiss, not a mechanism;
 * concentrating it around a centre frequency is what makes it read as a physical body being struck.
 */
function svfBandpass(input, sampleRate, centreHz, q) {
  const f = 2 * Math.sin((Math.PI * centreHz) / sampleRate);
  const damping = 1 / q;
  const out = new Float64Array(input.length);
  let low = 0;
  let band = 0;
  for (let i = 0; i < input.length; i += 1) {
    const high = input[i] - low - damping * band;
    band += f * high;
    low += f * band;
    out[i] = band;
  }
  return out;
}

/**
 * Cascaded one-pole lowpass, `poles` sections deep.
 *
 * A single pole is only -6dB/octave, which is far too gentle here: measured on the first pass it left the noise
 * burst with a spectral centroid above 6kHz, i.e. audibly hissy rather than mechanical. A real box clicker
 * measures nearer 2.5–3.5kHz. Cascading sections steepens the slope to -6·poles dB/octave, which is what actually
 * removes the "tss" without dulling the transient.
 */
function lowpassInPlace(buffer, sampleRate, cutoffHz, poles) {
  const a = 1 - Math.exp((-2 * Math.PI * cutoffHz) / sampleRate);
  for (let pole = 0; pole < poles; pole += 1) {
    let y = 0;
    for (let i = 0; i < buffer.length; i += 1) {
      y += a * (buffer[i] - y);
      buffer[i] = y;
    }
  }
}

/** One-pole highpass. Removes low-frequency thump, which on a phone speaker is inaudible energy that only eats headroom. */
function highpassInPlace(buffer, sampleRate, cutoffHz) {
  const rc = 1 / (2 * Math.PI * cutoffHz);
  const dt = 1 / sampleRate;
  const a = rc / (rc + dt);
  let previousIn = 0;
  let previousOut = 0;
  for (let i = 0; i < buffer.length; i += 1) {
    const x = buffer[i];
    const y = a * (previousOut + x - previousIn);
    buffer[i] = y;
    previousIn = x;
    previousOut = y;
  }
}

// ---------------------------------------------------------------------------------------------------------------
// Voice
// ---------------------------------------------------------------------------------------------------------------

function renderClick(spec) {
  const length = Math.round((spec.durationMs / 1000) * SAMPLE_RATE);
  const out = new Float64Array(length);
  const random = mulberry32(spec.seed);

  const secondAt = spec.secondTransientMs / 1000;

  // --- Body: the snap itself, as bandpassed noise under a very fast decay.
  const noise = new Float64Array(length);
  for (let i = 0; i < length; i += 1) noise[i] = random() * 2 - 1;
  const shapedNoise = svfBandpass(
    noise,
    SAMPLE_RATE,
    spec.noiseCentreHz,
    spec.noiseQ,
  );

  const noiseTau = spec.noiseDecayMs / 1000;
  for (let i = 0; i < length; i += 1) {
    const t = i / SAMPLE_RATE;
    let envelope = Math.exp(-t / noiseTau);
    const since = t - secondAt;
    if (since >= 0)
      envelope += spec.secondTransientGain * Math.exp(-since / noiseTau);
    out[i] += shapedNoise[i] * envelope * spec.noiseGain;
  }

  // --- Resonances: a few short damped modes give the mechanism its character.
  for (const mode of spec.modes) {
    const phase = random() * Math.PI * 2;
    const tau = mode.decayMs / 1000;
    for (let i = 0; i < length; i += 1) {
      const t = i / SAMPLE_RATE;
      let envelope = Math.exp(-t / tau);
      const since = t - secondAt;
      // The second strike excites the same modes, a little more weakly.
      if (since >= 0)
        envelope += spec.secondTransientGain * 0.6 * Math.exp(-since / tau);
      out[i] +=
        Math.sin(2 * Math.PI * mode.hz * t + phase) * envelope * mode.gain;
    }
  }

  // --- Attack shaping. Zero for the sharp candidates; a fraction of a millisecond takes the edge off the softer
  //     one without introducing anything that could be perceived as leading silence.
  const attackSamples = Math.round((spec.attackMs / 1000) * SAMPLE_RATE);
  for (let i = 0; i < attackSamples; i += 1) {
    out[i] *= 0.5 - 0.5 * Math.cos((Math.PI * i) / attackSamples);
  }

  highpassInPlace(out, SAMPLE_RATE, spec.highpassHz);
  lowpassInPlace(out, SAMPLE_RATE, spec.lowpassHz, spec.lowpassPoles);

  // --- Release. Applied after filtering, so the filters cannot reintroduce a non-zero final sample.
  const fadeSamples = Math.round((RELEASE_FADE_MS / 1000) * SAMPLE_RATE);
  for (let i = 0; i < fadeSamples; i += 1) {
    const index = length - fadeSamples + i;
    out[index] *= 0.5 + 0.5 * Math.cos((Math.PI * i) / fadeSamples);
  }
  out[length - 1] = 0;

  return out;
}

// ---------------------------------------------------------------------------------------------------------------
// Candidates
// ---------------------------------------------------------------------------------------------------------------

const CANDIDATES = [
  {
    id: "classic",
    file: "click-classic.wav",
    title: "A — Classic",
    intent:
      "Closest to a physical dog-training clicker. Neutral, dry, realistic.",
    seed: 0x9e3779b9,
    durationMs: 45,
    attackMs: 0,
    noiseCentreHz: 2600,
    noiseQ: 1.8,
    noiseDecayMs: 2.2,
    noiseGain: 1,
    secondTransientMs: 2.6,
    secondTransientGain: 0.28,
    highpassHz: 250,
    lowpassHz: 5600,
    lowpassPoles: 3,
    modes: [
      { hz: 1850, decayMs: 7, gain: 0.35 },
      { hz: 3200, decayMs: 5, gain: 0.22 },
      { hz: 4600, decayMs: 3.5, gain: 0.12 },
    ],
  },
  {
    id: "soft",
    file: "click-soft.wav",
    title: "B — Soft Premium",
    intent:
      "Warmer and less fatiguing for repeated daily use. Still immediate and crisp.",
    seed: 0x6a09e667,
    durationMs: 55,
    // A half-millisecond rise rounds the very tip of the transient. This is what removes the "spit" on a phone
    // speaker at close range; it is far too short to be perceived as a delay.
    attackMs: 0.5,
    noiseCentreHz: 1750,
    noiseQ: 1.6,
    noiseDecayMs: 3.0,
    noiseGain: 0.92,
    secondTransientMs: 3.2,
    secondTransientGain: 0.28,
    highpassHz: 180,
    // The defining move for this candidate: the top end is rolled off well before the others, which is what makes
    // it survive hundreds of repetitions in a training session without becoming tiring.
    lowpassHz: 4200,
    lowpassPoles: 3,
    modes: [
      { hz: 1250, decayMs: 10, gain: 0.42 },
      { hz: 2300, decayMs: 7, gain: 0.24 },
      { hz: 3400, decayMs: 4.5, gain: 0.1 },
    ],
  },
  {
    id: "crisp",
    file: "click-crisp.wav",
    title: "C — Crisp",
    intent:
      "Sharper and more cutting for louder environments. Still non-harsh and non-metallic.",
    seed: 0xbb67ae85,
    durationMs: 38,
    attackMs: 0,
    noiseCentreHz: 3600,
    noiseQ: 2.0,
    noiseDecayMs: 1.6,
    noiseGain: 1,
    secondTransientMs: 2.0,
    secondTransientGain: 0.4,
    highpassHz: 350,
    lowpassHz: 7000,
    lowpassPoles: 2,
    modes: [
      { hz: 2400, decayMs: 5, gain: 0.3 },
      { hz: 4200, decayMs: 3.5, gain: 0.2 },
      // Deliberately stops at 5.6kHz with a 2.5ms decay. Pushing a mode higher or letting it ring longer is the
      // difference between "crisp" and the metallic ping the brief rules out.
      { hz: 5600, decayMs: 2.5, gain: 0.1 },
    ],
  },
];

// ---------------------------------------------------------------------------------------------------------------
// Loudness matching
// ---------------------------------------------------------------------------------------------------------------

function rms(buffer) {
  let sum = 0;
  for (let i = 0; i < buffer.length; i += 1) sum += buffer[i] * buffer[i];
  return Math.sqrt(sum / buffer.length);
}

function peak(buffer) {
  let max = 0;
  for (let i = 0; i < buffer.length; i += 1)
    max = Math.max(max, Math.abs(buffer[i]));
  return max;
}

/**
 * Matches perceived loudness across candidates, then applies one shared gain.
 *
 * Normalising each file to the same *peak* would be wrong: the sharper candidate has a much higher peak-to-average
 * ratio, so peak-matching would leave it audibly quieter. Matching RMS first and only then scaling all three by a
 * single factor keeps them comparable in a listening test — which is the entire point of shipping three — while
 * still guaranteeing no file exceeds the ceiling.
 */
function matchLoudness(rendered) {
  const targetRms = rms(rendered[0].samples);
  for (const item of rendered) {
    const gain = targetRms / rms(item.samples);
    for (let i = 0; i < item.samples.length; i += 1) item.samples[i] *= gain;
  }

  const loudestPeak = Math.max(...rendered.map((item) => peak(item.samples)));
  const globalGain = PEAK_CEILING / loudestPeak;
  for (const item of rendered) {
    for (let i = 0; i < item.samples.length; i += 1)
      item.samples[i] *= globalGain;
  }
}

// ---------------------------------------------------------------------------------------------------------------
// WAV
// ---------------------------------------------------------------------------------------------------------------

function encodeWav(samples, sampleRate) {
  const dataBytes = samples.length * 2;
  const buffer = Buffer.alloc(44 + dataBytes);

  buffer.write("RIFF", 0, "ascii");
  buffer.writeUInt32LE(36 + dataBytes, 4);
  buffer.write("WAVE", 8, "ascii");
  buffer.write("fmt ", 12, "ascii");
  buffer.writeUInt32LE(16, 16); // PCM chunk size
  buffer.writeUInt16LE(1, 20); // PCM
  buffer.writeUInt16LE(1, 22); // mono
  buffer.writeUInt32LE(sampleRate, 24);
  buffer.writeUInt32LE(sampleRate * 2, 28); // byte rate
  buffer.writeUInt16LE(2, 32); // block align
  buffer.writeUInt16LE(16, 34); // bits per sample
  buffer.write("data", 36, "ascii");
  buffer.writeUInt32LE(dataBytes, 40);

  for (let i = 0; i < samples.length; i += 1) {
    // Clamp to 32767 rather than 32768 so the negative rail cannot wrap to full-scale positive.
    const clamped = Math.max(-1, Math.min(1, samples[i]));
    buffer.writeInt16LE(Math.round(clamped * 32767), 44 + i * 2);
  }

  return buffer;
}

// ---------------------------------------------------------------------------------------------------------------

const here = dirname(fileURLToPath(import.meta.url));
const outputDir = join(here, "..", "..", "apps", "mobile", "assets", "audio");
mkdirSync(outputDir, { recursive: true });

const rendered = CANDIDATES.map((spec) => ({
  spec,
  samples: renderClick(spec),
}));
matchLoudness(rendered);

for (const { spec, samples } of rendered) {
  const wav = encodeWav(samples, SAMPLE_RATE);
  writeFileSync(join(outputDir, spec.file), wav);

  const peakDb = (20 * Math.log10(peak(samples))).toFixed(2);
  const rmsDb = (20 * Math.log10(rms(samples))).toFixed(2);
  let peakIndex = 0;
  for (let i = 0; i < samples.length; i += 1) {
    if (Math.abs(samples[i]) === peak(samples)) {
      peakIndex = i;
      break;
    }
  }
  console.log(
    `${spec.file.padEnd(20)} ${String(spec.durationMs).padStart(3)}ms  ` +
      `peak ${peakDb} dBFS  rms ${rmsDb} dBFS  ` +
      `transient at ${((peakIndex / SAMPLE_RATE) * 1000).toFixed(2)}ms  ${wav.length} bytes`,
  );
}
